"""Single-file badminton agent for the arena (generated by build_agent.py).

Reads one JSON observation per line on stdin and writes one JSON input window
per line on stdout.  Contains a line-by-line Python port of the public physics
(catalog.js / simulation.js) used for forward planning, plus the planner and
the decision brain.
"""
import json
import math
import os
import sys


# ===================== physics (engine_py) =====================

"""Python port of the public badminton simulation (catalog.js + simulation.js).

Used only for offline self-testing. The physics here is a line-by-line port of
the public rules source so that plans produced by the agent can be verified
before submission.
"""

RULES = {
    "hz": 20.0,
    "substeps": 4,
    "decisionFrames": 10,
    "courtLength": 13.4,
    "netX": 6.7,
    "netHeight": 1.55,
    "netMin": 1.35,
    "netMax": 1.95,
    "netThickness": 0.09,
    "ceiling": 11.0,
    "gravity": 9.8,
    "shuttleDrag": 0.025,
    "shuttleRadius": 0.07,
    "matchPoints": 11,
    "maxPoints": 15,
    "winBy": 2,
    "matchSeconds": 240,
    "serveFreeze": 0.8,
    "pointFreeze": 0.7,
    "playerSpeed": 3.7,
    "playerAccel": 26.0,
    "playerFriction": 12.0,
    "playerHeight": 1.8,
    "shoulderHeight": 1.45,
    "jumpSpeed": 5.3,
    "playerGravity": 22.0,
    "playerRadius": 0.22,
    "staminaRunDrain": 9.0,
    "staminaRegen": 6.0,
    "staminaSwingCost": 7.0,
    "staminaChargeDrain": 12.0,
    "staminaSprintDrain": 26.0,
    "sprintMultiplier": 1.45,
    "sprintMinStamina": 5.0,
    "chargeRate": 1.3,
    "chargeDecay": 6.0,
    "chargeMoveFactor": 0.45,
    "chargeBoost": 0.55,
    "swingFrames": 9,
    "swingWindup": 2,
    "swingActive": 5,
    "swingCooldown": 0.40,
    "hitLock": 0.30,
    "reachRadius": 0.38,
}
OVERHEAD = {"fromUp": 2.10, "fromFwd": 0.05, "toUp": 1.25, "toFwd": 0.80}
UNDERARM = {"fromUp": 0.28, "fromFwd": 0.50, "toUp": 1.22, "toFwd": 0.68}
SHOT = {
    "overheadSpeed": 9.0, "overheadBoost": 3.0, "overheadSmashBonus": 7.5,
    "overheadAngleLow": 0.60, "overheadAngleHigh": -0.42,
    "clearHeight": 1.80, "smashHeight": 2.35,
    "liftSpeed": 9.0, "liftBoost": 2.0, "liftAngle": 1.05,
}
SERVE = {"vx": 7.0, "vy": 6.2, "height": 1.35, "offset": 0.45, "targetFromNet": 3.2}

DT = 1.0 / RULES["hz"]
SUB = DT / RULES["substeps"]


def clamp(v, a, b):
    return a if v < a else (b if v > b else v)


def js_round(v):
    return math.floor(v + 0.5)


def round2(v):
    return js_round(v * 100) / 100.0


def sign(v):
    return 1 if v > 0 else (-1 if v < 0 else 0)


def make_rng(seed):
    """Port of catalog.makeRng (LCG with 32-bit wrap-around)."""
    s = int(seed) % (2 ** 32) or 1

    def _r():
        nonlocal s
        s = (s * 1664525 + 1013904223) % (2 ** 32)
        return s / 4294967296.0

    return _r


def home_x(team):
    return RULES["courtLength"] * 0.25 if team == 0 else RULES["courtLength"] * 0.75


def make_player(team, name):
    return {
        "id": "p%d" % team, "team": team, "index": team, "name": name,
        "x": home_x(team), "y": 0.0, "vx": 0.0, "vy": 0.0, "onGround": True,
        "facing": 1 if team == 0 else -1,
        "swing": 0, "swingElapsed": 0, "swingType": 1, "swingCd": 0.0,
        "lastHitFrame": -999, "held": neutral(), "sprinting": False,
        "hits": 0, "smashes": 0, "errors": 0, "points": 0,
        "stamina": 100.0, "charge": 0.0,
    }


def neutral():
    return {"move": 0.0, "jump": False, "swing": 0, "charge": False, "sprint": False}


def make_shuttle(x, y):
    return {"x": x, "y": y, "vx": 0.0, "vy": 0.0, "lastTeam": None, "owner": None,
            "lastHitFrame": -999, "alive": True, "trail": []}


class Match:
    def __init__(self, seed=1, players=None, match_id="test"):
        if players is None:
            players = [{"name": "A", "kind": "api"}, {"name": "B", "kind": "api"}]
        self.id = match_id
        self.seed = seed
        net_rng = make_rng(int(seed) * 2654435761 + 97)
        self.netHeight = round((RULES["netMin"] + net_rng() * (RULES["netMax"] - RULES["netMin"])) * 100) / 100.0
        self.status = "playing"
        self.phase = "serve"
        self.winner = None
        self.reason = ""
        self.event_id = 0
        self.players = players
        self.frame = 0
        self.tick = 0
        self.score = [0, 0]
        self.server = 0
        self.serveTimer = 0
        self.pointTimer = 0
        self.rally = 0
        self.longestRally = 0
        self.lastPoint = None
        self.batsmen = [make_player(0, players[0]["name"]), make_player(1, players[1]["name"])]
        self.shuttle = None
        self.events = []
        self.pendingLanding = None
        self.begin_serve()

    # ---- events -------------------------------------------------------
    def emit(self, type_, data=None):
        self.event_id += 1
        ev = {"id": self.event_id, "t": round2(self.frame / RULES["hz"]),
              "frame": self.frame, "type": type_}
        if data:
            ev.update(data)
        self.events.append(ev)

    def begin_serve(self):
        p = self.batsmen[self.server]
        for b in self.batsmen:
            b.update({"x": home_x(b["team"]), "y": 0.0, "vx": 0.0, "vy": 0.0,
                      "onGround": True, "swing": 0, "swingElapsed": 0,
                      "swingCd": 0.0, "lastHitFrame": -999})
        self.shuttle = make_shuttle(p["x"] + p["facing"] * SERVE["offset"], SERVE["height"])
        self.shuttle["lastTeam"] = self.server
        self.phase = "serve"
        self.serveTimer = js_round(RULES["serveFreeze"] * RULES["hz"])
        self.rally = 0
        self.pendingLanding = None

    # ---- physics helpers ---------------------------------------------
    @staticmethod
    def in_swing_window(p):
        return (p["swing"] > 0 and p["swingElapsed"] >= RULES["swingWindup"]
                and p["swingElapsed"] < RULES["swingWindup"] + RULES["swingActive"])

    @staticmethod
    def racket_at(p, elapsed, swtype=None):
        if swtype is None:
            swtype = p["swingType"]
        frac = clamp(elapsed / float(RULES["swingFrames"]), 0.0, 1.0)
        arc = OVERHEAD if swtype > 0 else UNDERARM
        up = arc["fromUp"] + (arc["toUp"] - arc["fromUp"]) * frac
        fwd = arc["fromFwd"] + (arc["toFwd"] - arc["fromFwd"]) * frac
        return p["x"] + p["facing"] * fwd, p["y"] + up

    # ---- player -------------------------------------------------------
    def update_player(self, p):
        inp = p["held"] or {}
        try:
            move = clamp(float(inp.get("move", 0) or 0), -1.0, 1.0)
        except (TypeError, ValueError):
            move = 0.0
        accel = RULES["playerAccel"] if p["onGround"] else RULES["playerAccel"] * 0.35
        tired = 0.62 + 0.38 * p["stamina"] / 100.0
        charge_held = bool(inp.get("charge")) and p["onGround"] and p["stamina"] > 1
        sprint_held = (bool(inp.get("sprint")) and not charge_held and p["onGround"]
                       and move != 0 and p["stamina"] > RULES["sprintMinStamina"])
        if charge_held:
            p["charge"] = clamp(p["charge"] + RULES["chargeRate"] * DT, 0.0, 1.0)
        else:
            p["charge"] = max(0.0, p["charge"] - RULES["chargeDecay"] * DT)
        charged = 1.0 - (1.0 - RULES["chargeMoveFactor"]) * p["charge"]
        max_speed = RULES["playerSpeed"] * tired * charged * (RULES["sprintMultiplier"] if sprint_held else 1.0)
        p["sprinting"] = sprint_held

        if move != 0:
            p["vx"] += clamp(move * max_speed - p["vx"], -accel * DT, accel * DT)
        elif p["onGround"]:
            p["vx"] *= math.exp(-RULES["playerFriction"] * DT)
        else:
            p["vx"] *= math.exp(-1.5 * DT)

        running = abs(p["vx"]) > 3.2
        drain = 0.0
        if charge_held:
            drain += RULES["staminaChargeDrain"]
        if sprint_held:
            drain += RULES["staminaSprintDrain"]
        elif running:
            drain += RULES["staminaRunDrain"]
        if drain > 0:
            p["stamina"] = max(0.0, p["stamina"] - drain * DT)
        elif abs(p["vx"]) < 0.8 and p["onGround"]:
            p["stamina"] = min(100.0, p["stamina"] + RULES["staminaRegen"] * DT)

        if inp.get("jump") and p["onGround"] and p["stamina"] > 15:
            p["vy"] = RULES["jumpSpeed"]
            p["onGround"] = False
            p["stamina"] = max(0.0, p["stamina"] - 10)
        if not p["onGround"]:
            p["vy"] -= RULES["playerGravity"] * DT

        p["x"] += p["vx"] * DT
        p["y"] += p["vy"] * DT
        if p["y"] <= 0:
            p["y"] = 0.0
            p["vy"] = 0.0
            p["onGround"] = True

        lo = 0.35 if p["team"] == 0 else RULES["netX"] + 0.35
        hi = RULES["netX"] - 0.35 if p["team"] == 0 else RULES["courtLength"] - 0.35
        p["x"] = clamp(p["x"], lo, hi)

        if p["swingCd"] > 0:
            p["swingCd"] -= DT
        if p["swing"] > 0:
            p["swing"] -= 1
            p["swingElapsed"] += 1
        swing_dir = inp.get("swing", 0) or 0
        if isinstance(swing_dir, bool):
            swing_dir = 1 if swing_dir else 0
        if swing_dir != 0 and p["swing"] == 0 and p["swingCd"] <= 0:
            p["stamina"] = max(0.0, p["stamina"] - RULES["staminaSwingCost"])
            p["swing"] = RULES["swingFrames"]
            p["swingElapsed"] = 0
            p["swingType"] = 1 if swing_dir > 0 else -1
            p["swingCd"] = RULES["swingCooldown"] + RULES["swingFrames"] * DT

    # ---- shuttle ------------------------------------------------------
    def step_shuttle(self, dt):
        s = self.shuttle
        if not s["alive"]:
            return
        sp = math.hypot(s["vx"], s["vy"])
        drag = RULES["shuttleDrag"] * sp
        s["vx"] -= s["vx"] * drag * dt
        s["vy"] -= s["vy"] * drag * dt
        s["vy"] -= RULES["gravity"] * dt

        prev_x, prev_y = s["x"], s["y"]
        nx = s["x"] + s["vx"] * dt
        ny = s["y"] + s["vy"] * dt

        if ny > RULES["ceiling"]:
            ny = RULES["ceiling"]
            s["vy"] = -abs(s["vy"]) * 0.25

        crossed = (prev_x - RULES["netX"]) * (nx - RULES["netX"]) < 0
        if crossed:
            y_at_net = min(prev_y, ny)
            if y_at_net < self.netHeight + RULES["shuttleRadius"]:
                s["x"] = RULES["netX"] - sign(s["vx"]) * (RULES["netThickness"] + RULES["shuttleRadius"])
                s["vx"] *= -0.08
                s["vy"] *= 0.2
                self.emit("net", {"team": s["lastTeam"], "x": round2(s["x"]), "y": round2(s["y"])})
                return

        s["x"] = nx
        s["y"] = ny

        if s["x"] < -0.15 or s["x"] > RULES["courtLength"] + 0.15:
            s["alive"] = False
            s["vx"] = 0.0
            s["vy"] = 0.0
            self.pendingLanding = {"x": s["x"], "y": s["y"], "out": True}
            return
        if s["y"] <= RULES["shuttleRadius"]:
            s["y"] = RULES["shuttleRadius"]
            s["alive"] = False
            s["vx"] = 0.0
            s["vy"] = 0.0
            self.pendingLanding = {"x": s["x"], "y": 0.0}

    # ---- shot solving --------------------------------------------------
    @staticmethod
    def flight_landing(x, y, vx, vy):
        dt = SUB
        t = 0.0
        while t < 5.0:
            sp = math.hypot(vx, vy)
            vx -= vx * RULES["shuttleDrag"] * sp * dt
            vy -= vy * RULES["shuttleDrag"] * sp * dt
            vy -= RULES["gravity"] * dt
            x += vx * dt
            y += vy * dt
            if y > RULES["ceiling"]:
                y = RULES["ceiling"]
                vy = -abs(vy) * 0.25
            if y <= RULES["shuttleRadius"]:
                return x
            if x < -0.5 or x > RULES["courtLength"] + 0.5:
                return x
            t += dt
        return x

    @staticmethod
    def solve_speed(x0, y0, angle, dir_, target_x):
        lo, hi = 5.0, 34.0
        for _ in range(14):
            mid = (lo + hi) / 2.0
            land = Match.flight_landing(x0, y0, dir_ * mid * math.cos(angle), mid * math.sin(angle))
            if (land - target_x) * dir_ < 0:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2.0

    @staticmethod
    def shot_trace(x0, y0, angle, speed, dir_, net_h=None):
        if net_h is None:
            net_h = RULES["netHeight"]
        x, y = x0, y0
        vx = dir_ * speed * math.cos(angle)
        vy = speed * math.sin(angle)
        dt = SUB
        net_y = None
        t = 0.0
        while t < 5.0:
            sp = math.hypot(vx, vy)
            vx -= vx * RULES["shuttleDrag"] * sp * dt
            vy -= vy * RULES["shuttleDrag"] * sp * dt
            vy -= RULES["gravity"] * dt
            px, py = x, y
            x += vx * dt
            y += vy * dt
            if net_y is None and (px - RULES["netX"]) * (x - RULES["netX"]) <= 0 and abs(x - px) > 1e-9:
                f = (RULES["netX"] - px) / (x - px)
                net_y = py + (y - py) * f
            if y > RULES["ceiling"]:
                y = RULES["ceiling"]
                vy = -abs(vy) * 0.25
            net_hit = net_y is not None and net_y < net_h + RULES["shuttleRadius"] + 0.03
            if y <= RULES["shuttleRadius"]:
                return {"netY": net_y, "landX": x, "netHit": net_hit}
            if x < -0.2 or x > RULES["courtLength"] + 0.2:
                return {"netY": net_y, "landX": x, "netHit": net_hit}
            t += dt
        net_hit = net_y is not None and net_y < net_h + RULES["shuttleRadius"] + 0.03
        return {"netY": net_y, "landX": x, "netHit": net_hit}

    @staticmethod
    def serve_launch(x0, y0, dir_, target, net_h=None):
        """Pick the serve angle/speed the engine will use (raised for high nets)."""
        if net_h is None:
            net_h = RULES["netHeight"]
        angle, speed = 0.72, 0.0
        for a in (0.72, 0.85, 1.0, 1.15, 1.3):
            angle = a
            speed = Match.solve_speed(x0, y0, a, dir_, target)
            tr = Match.shot_trace(x0, y0, a, speed, dir_, net_h)
            if not tr["netHit"]:
                break
        return angle, speed

    @staticmethod
    def choose_shot(x, y, dir_, kind, target, net_h=None):
        if net_h is None:
            net_h = RULES["netHeight"]
        ranges = {
            "smash": [-0.42, -0.30, -0.18, -0.06, 0.06, 0.16, 0.26, 0.34],
            "clear": [0.60, 0.72, 0.85],
            "drop": [0.42, 0.55, 0.68],
            "lift": [1.05, 1.20],
        }
        for angle in ranges[kind]:
            speed = Match.solve_speed(x, y, angle, dir_, target)
            tr = Match.shot_trace(x, y, angle, speed, dir_, net_h)
            if not tr["netHit"] and -0.05 < tr["landX"] < RULES["courtLength"] + 0.05:
                return angle, speed
        angle = 0.30 if kind == "smash" else (0.75 if kind == "clear" else (0.60 if kind == "drop" else 1.15))
        return angle, Match.solve_speed(x, y, angle, dir_, target)

    @staticmethod
    def shot_kind_and_target(sx, sy, swing_type, facing, opp_x):
        """Replicates the kind/target selection inside strike()."""
        dir_ = facing
        if swing_type > 0:
            t = clamp((sy - SHOT["clearHeight"]) / (SHOT["smashHeight"] - SHOT["clearHeight"]), 0.0, 1.0)
            dist_net = abs(sx - RULES["netX"])
            near = clamp(1.0 - (dist_net - 3.2) / 2.5, 0.0, 1.0)
            smash = t * near
            opp_deep = abs(opp_x - RULES["netX"]) > 3.0
            if smash > 0.55:
                kind = "smash"
                short_x = RULES["netX"] + dir_ * 1.6
                deep_x = RULES["courtLength"] - 1.0 if dir_ > 0 else 1.0
                target = short_x if abs(short_x - opp_x) >= abs(deep_x - opp_x) else deep_x
            elif t > 0.5 and opp_deep and dist_net > 2.6:
                kind = "drop"
                target = RULES["netX"] + dir_ * 2.7
            else:
                kind = "clear"
                target = 11.9 if dir_ > 0 else RULES["courtLength"] - 11.9
        else:
            kind = "lift"
            target = 11.4 if dir_ > 0 else RULES["courtLength"] - 11.4
        return kind, target

    # ---- strike / hit --------------------------------------------------
    def strike(self, p, sx, sy):
        s = self.shuttle
        forward = clamp((p["held"].get("move", 0) or 0) * p["facing"], 0.0, 1.0)
        opp = self.batsmen[1 - p["team"]]
        kind, target = self.shot_kind_and_target(sx, sy, p["swingType"], p["facing"], opp["x"])
        target += p["facing"] * forward * 0.6
        angle, speed = self.choose_shot(sx, sy, p["facing"], kind, target, self.netHeight)
        speed *= 1.0 + RULES["chargeBoost"] * p["charge"]
        p["charge"] = 0.0
        s["vx"] = p["facing"] * speed * math.cos(angle)
        s["vy"] = speed * math.sin(angle)
        s["x"] = sx
        s["y"] = sy
        s["lastTeam"] = p["team"]
        s["owner"] = p["id"]
        s["lastHitFrame"] = self.frame
        s["trail"] = []
        p["lastHitFrame"] = self.frame
        p["hits"] += 1
        self.rally += 1
        self.longestRally = max(self.longestRally, self.rally)
        self.emit("hit", {"team": p["team"], "kind": kind, "x": round2(sx),
                          "y": round2(sy), "speed": round2(speed)})

    def try_hit(self, p, sx, sy):
        if not self.in_swing_window(p):
            return False
        if self.frame - p["lastHitFrame"] < RULES["hitLock"] * RULES["hz"]:
            return False
        s = self.shuttle
        if not s["alive"]:
            return False
        if p["team"] == 0 and s["x"] > RULES["netX"] + 0.3:
            return False
        if p["team"] == 1 and s["x"] < RULES["netX"] - 0.3:
            return False
        rx, ry = self.racket_at(p, p["swingElapsed"], p["swingType"])
        reach = RULES["reachRadius"] * (0.82 + 0.18 * p["stamina"] / 100.0)
        if math.hypot(sx - rx, sy - ry) > reach:
            return False
        self.strike(p, sx, sy)
        return True

    # ---- point ---------------------------------------------------------
    def resolve_point(self):
        land = self.pendingLanding
        if not land:
            return
        self.pendingLanding = None
        s = self.shuttle
        last = 0 if s["lastTeam"] is None else s["lastTeam"]
        if land.get("out"):
            winner = 1 - last
            reason = "出界"
        else:
            side = 0 if land["x"] < RULES["netX"] else 1
            winner = 1 - last if side == last else last
            reason = "落在自己半场" if side == last else "落在对方半场"
        self.score[winner] += 1
        self.batsmen[winner]["points"] += 1
        self.server = winner
        self.lastPoint = {"winner": winner, "reason": reason, "rally": self.rally,
                          "x": round2(land["x"]), "out": bool(land.get("out"))}
        self.emit("point", {"team": winner, "score": list(self.score), "reason": reason,
                            "rally": self.rally, "x": round2(land["x"])})
        a, b = self.score
        hi, lo = max(a, b), min(a, b)
        if (hi >= RULES["matchPoints"] and hi - lo >= RULES["winBy"]) or hi >= RULES["maxPoints"]:
            self.finish(0 if a > b else 1, "比分 %d:%d" % (a, b))
            return
        self.phase = "point"
        self.pointTimer = js_round(RULES["pointFreeze"] * RULES["hz"])

    def finish(self, winner, reason):
        if self.status == "finished":
            return
        self.status = "finished"
        self.phase = "finished"
        self.winner = winner
        self.reason = reason
        self.emit("finish", {"team": winner, "reason": reason, "score": list(self.score)})

    # ---- main step -----------------------------------------------------
    def step(self):
        if self.status != "playing":
            return
        self.frame += 1
        self.tick += 1

        if self.phase == "serve":
            self.serveTimer -= 1
            if self.serveTimer <= 0:
                p = self.batsmen[self.server]
                target = RULES["netX"] + p["facing"] * SERVE["targetFromNet"]
                angle, speed = self.serve_launch(self.shuttle["x"], self.shuttle["y"],
                                                 p["facing"], target, self.netHeight)
                self.shuttle["vx"] = p["facing"] * speed * math.cos(angle)
                self.shuttle["vy"] = speed * math.sin(angle)
                self.shuttle["lastTeam"] = self.server
                self.shuttle["lastHitFrame"] = self.frame
                self.phase = "rally"
                self.emit("serve", {"team": self.server})

        for p in self.batsmen:
            self.update_player(p)

        if self.phase == "rally":
            s = self.shuttle
            for _ in range(RULES["substeps"]):
                self.step_shuttle(SUB)
                for p in self.batsmen:
                    if self.try_hit(p, s["x"], s["y"]):
                        break
                if not s["alive"] or self.pendingLanding:
                    break
            if s["alive"]:
                s["trail"].append({"x": round2(s["x"]), "y": round2(s["y"])})
                if len(s["trail"]) > 14:
                    s["trail"].pop(0)
            if self.pendingLanding:
                self.resolve_point()
        elif self.phase == "point":
            self.pointTimer -= 1
            if self.pointTimer <= 0:
                self.begin_serve()

        if self.status == "playing" and self.frame >= RULES["matchSeconds"] * RULES["hz"]:
            a, b = self.score
            if a == b:
                self.finish(None, "时间到，%d:%d 平局" % (a, b))
            else:
                self.finish(0 if a > b else 1, "时间到，%d:%d" % (max(a, b), min(a, b)))

    # ---- observation ---------------------------------------------------
    def public_player(self, p):
        return {
            "id": p["id"], "team": p["team"], "index": p["index"], "name": p["name"],
            "x": round2(p["x"]), "y": round2(p["y"]), "vx": round2(p["vx"]), "vy": round2(p["vy"]),
            "onGround": p["onGround"], "facing": p["facing"], "sprinting": bool(p["sprinting"]),
            "swing": p["swing"], "swingElapsed": p["swingElapsed"], "swingType": p["swingType"],
            "swinging": self.in_swing_window(p),
            "swingCd": round2(max(0.0, p["swingCd"])),
            "stamina": round2(p["stamina"]), "charge": round2(p["charge"]),
            "hits": p["hits"], "smashes": p["smashes"], "points": p["points"],
        }

    def view(self, viewer=None):
        s = self.shuttle
        return {
            "id": self.id, "seed": self.seed, "tick": self.tick, "frame": self.frame,
            "status": self.status, "phase": self.phase, "winner": self.winner,
            "reason": self.reason, "yourPlayer": viewer,
            "players": [dict(p) for p in self.players],
            "score": list(self.score), "server": self.server,
            "serveLeft": round2(max(0.0, self.serveTimer / RULES["hz"])),
            "pointLeft": round2(max(0.0, self.pointTimer / RULES["hz"])),
            "rally": self.rally, "longestRally": self.longestRally,
            "lastPoint": self.lastPoint,
            "timeLeft": round2(max(0.0, RULES["matchSeconds"] - self.frame / RULES["hz"])),
            "batsmen": [self.public_player(p) for p in self.batsmen],
            "shuttle": None if s is None else {
                "x": round2(s["x"]), "y": round2(s["y"]), "vx": round2(s["vx"]),
                "vy": round2(s["vy"]), "alive": s["alive"], "lastTeam": s["lastTeam"],
                "owner": s["owner"], "trail": s["trail"][-14:],
            },
            "court": {"length": RULES["courtLength"], "netX": RULES["netX"],
                      "netHeight": self.netHeight, "ceiling": RULES["ceiling"]},
            "rules": dict(RULES),
            "events": self.events[-60:],
        }


def normalize_unit_input(inp):
    out = neutral()
    if inp is None:
        return out
    if not isinstance(inp, dict):
        raise ValueError("input must be an object")
    if inp.get("move") is not None:
        v = float(inp["move"])
        if v != v or v in (float("inf"), float("-inf")):
            raise ValueError("bad move")
        out["move"] = clamp(v, -1.0, 1.0)
    out["jump"] = bool(inp.get("jump"))
    out["charge"] = bool(inp.get("charge"))
    out["sprint"] = bool(inp.get("sprint"))
    if inp.get("swing") is not None:
        sw = inp["swing"]
        if isinstance(sw, bool):
            out["swing"] = 1 if sw else 0
        else:
            v = float(sw)
            out["swing"] = 1 if v > 0.1 else (-1 if v < -0.1 else 0)
    return out


def normalize_frame(frame):
    if isinstance(frame, list):
        if len(frame) != 1:
            raise ValueError("each frame must hold exactly 1 player")
        return [normalize_unit_input(frame[0])]
    return [normalize_unit_input(frame)]


def advance_window(g, windows):
    steps = 0
    for i in range(RULES["decisionFrames"]):
        if g.status != "playing":
            break
        for b in g.batsmen:
            win = windows[b["team"]] if b["team"] < len(windows) else None
            frame = win[i] if win and i < len(win) else None
            b["held"] = (frame[0] if frame else neutral())
        g.step()
        steps += 1
    return steps


def run_match(agent0, agent1, seed=1, match_id="test", max_windows=2000, on_window=None):
    g = Match(seed=seed, match_id=match_id)
    w = 0
    while g.status == "playing" and w < max_windows:
        o0 = g.view(0)
        o1 = g.view(1)
        w0 = agent0.act(o0)
        w1 = agent1.act(o1)
        win0 = [normalize_frame(f) for f in w0]
        win1 = [normalize_frame(f) for f in w1]
        advance_window(g, [win0, win1])
        w += 1
        if on_window:
            on_window(g, w)
    return g

# module alias so the ported modules can keep using E.*
E = sys.modules[__name__]


# ===================== planner =====================

"""Planning core for the badminton agent (offline development version).

Depends on engine_py for the exact physics. At submission time this module is
bundled with engine_py into a single self-contained agent.py.
"""
import os


R = E.RULES
DT = E.DT
SUB = E.SUB
# Sprint only above this stamina: below it the 1.45x multiplier is small while
# the 26/s drain is not, so sprinting mostly just empties the tank.
SPRINT_MIN_STAMINA = float(os.environ.get("BAD_SPRINT_MIN", "18"))


def clamp(v, a, b):
    return a if v < a else (b if v > b else v)


# --------------------------------------------------------------------------
# Racket geometry
# --------------------------------------------------------------------------
def racket_offsets(elapsed, swtype):
    frac = clamp(elapsed / float(R["swingFrames"]), 0.0, 1.0)
    arc = E.OVERHEAD if swtype > 0 else E.UNDERARM
    up = arc["fromUp"] + (arc["toUp"] - arc["fromUp"]) * frac
    fwd = arc["fromFwd"] + (arc["toFwd"] - arc["fromFwd"]) * frac
    return up, fwd


def reach_of(stamina):
    return R["reachRadius"] * (0.82 + 0.18 * stamina / 100.0)


def max_speed_of(stamina):
    return R["playerSpeed"] * (0.62 + 0.38 * stamina / 100.0)


# Feet height on frames 1..8 after a jump (engine Euler integration: vy=5.3,
# gravity 22, position updated after the gravity step).  Apex 0.51 at frame 4.
JUMP_Y = (0.21, 0.365, 0.465, 0.51, 0.50, 0.435, 0.315, 0.14)


def jump_frame_for(py_req, t, tol=0.11):
    """Jump frame (1-based in the window) putting the feet at py_req on frame t.

    Returns (jump_frame, residual) or None when no frame fits within tol.
    """
    best = None
    for n, y in enumerate(JUMP_Y, start=1):
        jf = t - n
        if jf < 1:
            continue
        d = abs(y - py_req)
        if best is None or d < best[0]:
            best = (d, jf)
    if best is None or best[0] > tol:
        return None
    return best[1], best[0]


# --------------------------------------------------------------------------
# Shuttle prediction
# --------------------------------------------------------------------------
def shuttle_step(state, dt, net=True):
    """Advance a shuttle dict by dt. Returns 'net' if it hit the net."""
    x, y, vx, vy = state["x"], state["y"], state["vx"], state["vy"]
    sp = math.hypot(vx, vy)
    drag = R["shuttleDrag"] * sp
    vx -= vx * drag * dt
    vy -= vy * drag * dt
    vy -= R["gravity"] * dt
    prev_x, prev_y = x, y
    nx = x + vx * dt
    ny = y + vy * dt
    if ny > R["ceiling"]:
        ny = R["ceiling"]
        vy = -abs(vy) * 0.25
    if net:
        crossed = (prev_x - R["netX"]) * (nx - R["netX"]) < 0
        if crossed:
            y_at_net = min(prev_y, ny)
            if y_at_net < R["netHeight"] + R["shuttleRadius"]:
                x = R["netX"] - E.sign(vx) * (R["netThickness"] + R["shuttleRadius"])
                vx *= -0.08
                vy *= 0.2
                state.update(x=x, y=y, vx=vx, vy=vy, alive=True)
                return "net"
    x, y = nx, ny
    landed = False
    if x < -0.15 or x > R["courtLength"] + 0.15:
        landed = True
        state.update(x=x, y=y, vx=0.0, vy=0.0, alive=False)
        return "out"
    if y <= R["shuttleRadius"]:
        y = R["shuttleRadius"]
        landed = True
        state.update(x=x, y=y, vx=0.0, vy=0.0, alive=False)
        return "land"
    state.update(x=x, y=y, vx=vx, vy=vy, alive=True)
    return None


def predict_shuttle(shuttle, nframes):
    """Predict the shuttle for nframes frames.

    Returns list of length nframes+1; entry f is the list of substep samples
    (x, y, alive) taken during frame f (index 0 = current state, empty list).
    """
    st = {k: shuttle[k] for k in ("x", "y", "vx", "vy", "alive")}
    out = [[(st["x"], st["y"], st["alive"])]]
    for f in range(1, nframes + 1):
        samples = []
        for _ in range(R["substeps"]):
            if not st["alive"]:
                samples.append((st["x"], st["y"], False))
                continue
            res = shuttle_step(st, SUB)
            samples.append((st["x"], st["y"], st["alive"]))
            if res in ("land", "out"):
                break
        out.append(samples)
        if not st["alive"]:
            # pad remaining frames
            for _ in range(nframes - f):
                out.append([(st["x"], st["y"], False)])
            break
    while len(out) < nframes + 1:
        out.append([(st["x"], st["y"], False)])
    return out


def predict_serve(shuttle, release_in_frames, server_facing, nframes):
    """Predict a serve from the frozen shuttle state until nframes frames.

    release_in_frames: how many frames until the serve leaves the server's
    racket (0 or negative means it has already been released).
    """
    st = {k: shuttle[k] for k in ("x", "y", "vx", "vy", "alive")}
    out = [[(st["x"], st["y"], st["alive"])]]
    target = R["netX"] + server_facing * E.SERVE["targetFromNet"]
    release = max(1, int(release_in_frames))
    for f in range(1, nframes + 1):
        if f < release:
            # frozen on the server's racket
            out.append([(st["x"], st["y"], st["alive"])])
            continue
        if f == release:
            angle, speed = E.Match.serve_launch(st["x"], st["y"], server_facing, target,
                                                R["netHeight"])
            st["vx"] = server_facing * speed * math.cos(angle)
            st["vy"] = speed * math.sin(angle)
        samples = []
        for _ in range(R["substeps"]):
            if not st["alive"]:
                samples.append((st["x"], st["y"], False))
                continue
            res = shuttle_step(st, SUB)
            samples.append((st["x"], st["y"], st["alive"]))
            if res in ("land", "out"):
                break
        out.append(samples)
        if not st["alive"]:
            for _ in range(nframes - f):
                out.append([(st["x"], st["y"], False)])
            break
    while len(out) < nframes + 1:
        out.append([(st["x"], st["y"], False)])
    return out


# --------------------------------------------------------------------------
# Player simulation
# --------------------------------------------------------------------------
def player_state_from_obs(b, team):
    p = E.make_player(team, "me")
    for k in ("x", "y", "vx", "vy", "onGround", "facing", "swing", "swingElapsed",
              "swingType", "swingCd", "stamina", "charge"):
        if k in b:
            p[k] = b[k]
    p["stamina"] = float(b.get("stamina", 100.0))
    p["charge"] = float(b.get("charge", 0.0))
    p["lastHitFrame"] = -999
    return p


class DummyMatch:
    """Minimal host object so we can reuse Match.update_player."""
    def __init__(self):
        self.frame = 0
        self.events = []
        self.event_id = 0
        self.batsmen = []
        self.shuttle = None
        self.pendingLanding = None

    def emit(self, *a, **k):
        pass


def sim_player(p, inputs, nframes):
    """Simulate a player for nframes with the given per-frame input dicts.

    Returns a list of snapshots (dicts) per frame, index 0 = start state.
    """
    host = DummyMatch()
    q = {k: (dict(v) if isinstance(v, dict) else v) for k, v in p.items()}
    traj = [dict(q)]
    for i in range(nframes):
        q["held"] = inputs[i] if i < len(inputs) else E.neutral()
        E.Match.update_player(host, q)
        traj.append(dict(q))
    return traj


def servo_inputs(p, target_x, at_frame, jump_at=None, nframes=None, hold_after=False,
                 allow_sprint=True):
    """Produce per-frame inputs that bring the player to target_x at at_frame."""
    if nframes is None:
        nframes = max(at_frame, 1)
    p0 = p
    inputs = []
    for i in range(nframes):
        f = i + 1
        left = at_frame - i
        dx = target_x - p0["x"]
        base = max_speed_of(p0["stamina"])
        can_sprint = (allow_sprint and p0["stamina"] > SPRINT_MIN_STAMINA
                      and p0["onGround"])
        top = base * (R["sprintMultiplier"] if can_sprint else 1.0)
        if left > 0:
            v_des = clamp(dx / (left * DT), -top, top)
        else:
            v_des = 0.0
        sprint = abs(v_des) > base + 0.03
        denom = base * (R["sprintMultiplier"] if sprint else 1.0)
        mv = clamp(v_des / denom, -1.0, 1.0) if denom > 1e-6 else 0.0
        if hold_after and f > at_frame:
            mv = 0.0
            sprint = False
        inp = {"move": mv, "sprint": sprint}
        if jump_at is not None and f == jump_at:
            inp["jump"] = True
        inputs.append(inp)
        # advance a copy to keep the servo state current
        q = dict(p0)
        q["held"] = inp
        E.Match.update_player(DummyMatch(), q)
        p0 = q
    return inputs


def reach_at(p, frames):
    """Fastest forward/backward reachable x after `frames` frames."""
    fwd = servo_inputs(p, 100.0, frames)
    back = servo_inputs(p, -100.0, frames)
    tf = sim_player(p, fwd, frames)
    tb = sim_player(p, back, frames)
    return tf[-1]["x"], tb[-1]["x"]


def plan_control(p, target_x, at_frame, nframes, jump_at=None, hold_after=True,
                 allow_sprint=True):
    """Servo to target_x at at_frame, with one correction pass, then verification."""
    inputs = servo_inputs(p, target_x, at_frame, jump_at, nframes, hold_after,
                          allow_sprint=allow_sprint)
    for _ in range(2):
        traj = sim_player(p, inputs, nframes)
        if at_frame >= len(traj):
            break
        actual = traj[at_frame]["x"]
        err = target_x - actual
        if abs(err) < 0.005:
            break
        target_x2 = target_x + err
        inputs = servo_inputs(p, target_x2, at_frame, jump_at, nframes, hold_after,
                              allow_sprint=allow_sprint)
        target_x = target_x2
    return inputs


# --------------------------------------------------------------------------
# Shot evaluation
# --------------------------------------------------------------------------
def shot_from_contact(sx, sy, swtype, facing, opp_x, charge=0.0, forward=0.0):
    kind, target = E.Match.shot_kind_and_target(sx, sy, swtype, facing, opp_x)
    target += facing * clamp(forward, 0.0, 1.0) * 0.6
    angle, speed = E.Match.choose_shot(sx, sy, facing, kind, target)
    speed *= 1.0 + R["chargeBoost"] * charge
    return {"kind": kind, "target": target, "angle": angle, "speed": speed}


def simulate_shot(sx, sy, shot, facing, nframes=60):
    """Full flight samples of a struck shuttle: list of (frame, x, y)."""
    st = {"x": sx, "y": sy,
          "vx": facing * shot["speed"] * math.cos(shot["angle"]),
          "vy": shot["speed"] * math.sin(shot["angle"]),
          "alive": True}
    out = []
    for f in range(1, nframes + 1):
        for _ in range(R["substeps"]):
            if not st["alive"]:
                break
            res = shuttle_step(st, SUB)
            if res in ("land", "out"):
                break
        out.append((f, st["x"], st["y"]))
        if not st["alive"]:
            break
    return out


def opponent_can_reach(traj, opp_x, opp_stamina, team_of_opp, extra_move=0.0):
    """Rough check whether the opponent can intercept the shot before it lands."""
    maxs = max_speed_of(opp_stamina)
    reach = reach_of(opp_stamina)
    for (f, x, y) in traj:
        t = f * DT
        # ball must be on the opponent's side to be hittable
        if team_of_opp == 0 and x > R["netX"] + 0.3:
            continue
        if team_of_opp == 1 and x < R["netX"] - 0.3:
            continue
        if y > 2.35 or y < 0.05:
            continue
        # they can be anywhere within maxs*t of their current x (plus a bit)
        d = abs(x - opp_x)
        travel = maxs * t + 0.5 * R["playerAccel"] * min(t, maxs / R["playerAccel"]) ** 2
        if d <= travel + reach + 0.55 + extra_move:
            return True, f
    return False, None


# --------------------------------------------------------------------------
# Interception planning
# --------------------------------------------------------------------------
def best_contacts(ball_pred, team, p, opp, horizon, stamina_hint=None):
    """Enumerate candidate (frame, elapsed, swtype) contacts for the player.

    Returns a list of dicts sorted by (score desc).
    """
    facing = p["facing"]
    st = stamina_hint if stamina_hint is not None else p["stamina"]
    reach = reach_of(st)
    cands = []
    for t in range(1, min(horizon, len(ball_pred) - 1) + 1):
        samples = [s for s in ball_pred[t] if s[2]]
        if not samples:
            continue
        for swtype in (1, -1):
            for e in range(R["swingWindup"], R["swingWindup"] + R["swingActive"]):
                up, fwd = racket_offsets(e, swtype)
                best = None
                for (bx, by, alive) in samples:
                    if team == 0 and bx > R["netX"] + 0.3:
                        continue
                    if team == 1 and bx < R["netX"] - 0.3:
                        continue
                    # feet height: assume ground unless already airborne
                    py = p["y"]
                    dy = by - (py + up)
                    if abs(dy) > reach:
                        continue
                    half = math.sqrt(max(0.0, reach * reach - dy * dy))
                    px = bx - facing * fwd
                    if best is None or half > best[2]:
                        best = (px, half, half)
                if best is None:
                    continue
                cands.append({"t": t, "e": e, "swtype": swtype, "px": best[0],
                              "margin": best[1]})
    return cands

# ===================== brain =====================

"""Agent brain (development version). Bundled into agent.py for submission."""


R = E.RULES
DT = E.DT
SUB = E.SUB

KIND_BASE = {"smash": 100.0, "drop": 62.0, "clear": 38.0, "lift": 22.0}

# Jumping costs 10 stamina and 8 frames of heavy air control, so only do it
# when there is a real down-press to win (or a ball we cannot reach at all).
JUMP_MIN_STAMINA = float(os.environ.get("BAD_JUMP_MIN", "22"))

DEBUG = bool(os.environ.get("BAD_DEBUG"))


def log(*a):
    if DEBUG:
        print(*a, file=sys.stderr)


def neutral_window():
    return [E.neutral() for _ in range(10)]


def opp_x_at(opp, t):
    x = opp["x"] + opp["vx"] * t * DT
    if opp["team"] == 0:
        return clamp(x, 0.35, R["netX"] - 0.35)
    return clamp(x, R["netX"] + 0.35, R["courtLength"] - 0.35)


def in_window(p):
    return (p["swing"] > 0 and p["swingElapsed"] >= R["swingWindup"]
            and p["swingElapsed"] < R["swingWindup"] + R["swingActive"])


def shot_frames(sx, sy, shot, facing, nframes):
    """Substep samples per frame of a struck shuttle (index 0 = contact frame)."""
    st = {"x": sx, "y": sy,
          "vx": facing * shot["speed"] * math.cos(shot["angle"]),
          "vy": shot["speed"] * math.sin(shot["angle"]),
          "alive": True}
    out = [[(sx, sy, True)]]
    for f in range(1, nframes + 1):
        samples = []
        for _ in range(R["substeps"]):
            if not st["alive"]:
                samples.append((st["x"], st["y"], False))
                continue
            res = shuttle_step(st, SUB)
            samples.append((st["x"], st["y"], st["alive"]))
            if res in ("land", "out"):
                break
        out.append(samples)
        if not st["alive"]:
            for _ in range(nframes - f):
                out.append([(st["x"], st["y"], False)])
            break
    while len(out) < nframes + 1:
        out.append([(st["x"], st["y"], False)])
    return out


def shot_frames_partial(sx, sy, shot, facing, rem_substeps, nframes):
    """Samples of a struck shuttle when the contact happened mid-frame.

    The engine calls tryHit() after each of the four physics substeps, so a
    hit on substep j leaves 3-j substeps of travel inside the contact frame.
    Treating the contact point as the frame boundary (rem=0) lags the real
    trajectory by up to one frame -- ~0.9 grid at smash speed, which is more
    than the 0.38 racket reach.  index 0 is the contact frame.

    rem_substeps may also be a float in [0,3] (fractional-phase estimate);
    the split is then rounded to substeps for the trajectory itself.
    """
    st = {"x": sx, "y": sy,
          "vx": facing * shot["speed"] * math.cos(shot["angle"]),
          "vy": shot["speed"] * math.sin(shot["angle"]),
          "alive": True}
    nrem = int(clamp(round(float(rem_substeps)), 0, R["substeps"] - 1))
    frame0 = [(sx, sy, True)]
    alive = True
    for _ in range(nrem):
        if not alive:
            break
        res = shuttle_step(st, SUB)
        frame0.append((st["x"], st["y"], st["alive"]))
        if res in ("land", "out"):
            alive = False
    out = [frame0]
    for f in range(1, nframes + 1):
        if not alive:
            out.append([(st["x"], st["y"], False)])
            continue
        samples = []
        for _ in range(R["substeps"]):
            if not st["alive"]:
                samples.append((st["x"], st["y"], False))
                continue
            res = shuttle_step(st, SUB)
            samples.append((st["x"], st["y"], st["alive"]))
            if res in ("land", "out"):
                alive = False
                break
        out.append(samples)
    return out


def contact_substep(frame_samples, cx, cy):
    """Index (0..3) of the substep inside a frame whose sample matches (cx,cy)."""
    best = None
    for j, (bx, by, alive) in enumerate(frame_samples):
        d = math.hypot(bx - cx, by - cy)
        if best is None or d < best[0]:
            best = (d, j)
    if best is None:
        return None
    return best[1] if best[0] < 0.25 else None


class Brain:
    def __init__(self, def_mode=None, smash_lover=False, no_sprint=False, nudge=False, learn=True, clear_lover=False):
        self.debug_hits = []
        self.def_mode = def_mode or os.environ.get("BAD_DEF", "mid")
        self.smash_lover = smash_lover
        self.clear_lover = clear_lover
        self.no_sprint = no_sprint
        self.nudge = nudge
        self.learn = learn
        self.runup = os.environ.get("BAD_RUNUP", "1") != "0"
        self.rally_sprint = os.environ.get("BAD_RALLY_SPRINT", "1") != "0"
        self.move_pen = float(os.environ.get("BAD_MOVE_PEN", "6"))
        self.jump_pen = float(os.environ.get("BAD_JUMP_PEN", "14"))
        # Net-clearance safety: the engine checks min(y_prev,y_next) per
        # substep, which for a fast descending smash is up to ~0.1 lower
        # than the interpolated crossing used by shot_trace().
        self.net_margin = float(os.environ.get("BAD_NET_MARGIN", "0.10"))
        self.deadbait = os.environ.get("BAD_BAIT", "1") != "0"
        self.bait_hold_until = -1
        self.seen_event = 0
        self.return_contacts = []       # (x, y, offset) of opponent serve returns
        self.last_return_swtype = None  # 1 overhead / -1 underarm, learned from hit kind
        self.last_return_speed = None   # initial speed of that return, for target inversion
        self.plan_tail = []             # inputs of the current plan past frame 10
        self.plan_tail_frame0 = -1      # absolute frame that plan_tail[0] applies to
        self.serve_release = None       # frame our current serve left the racket
        self.serve_hit_pending = False

    # ------------------------------------------------------------------
    def act(self, obs):
        try:
            return self._act(obs)
        except Exception:
            if DEBUG:
                import traceback
                traceback.print_exc()
            return neutral_window()

    def _act(self, obs):
        team = obs.get("yourPlayer")
        if obs.get("status") != "playing" or team is None:
            return neutral_window()
        # A single process may serve several games of a round (seats swap and
        # the net height changes).  Learning state is per game.
        key = (obs.get("id"), obs.get("seed"))
        if key != getattr(self, "match_key", None):
            self.match_key = key
            self.seen_event = 0
            self.return_contacts = []
            self.last_return_swtype = None
            self.last_return_speed = None
            self.plan_tail = []
            self.plan_tail_frame0 = -1
            self.serve_release = None
            self.serve_hit_pending = False
            self.bait_hold_until = -1
        self._observe(obs, team)
        court = obs.get("court") or {}
        nh = court.get("netHeight")
        if nh is not None:
            try:
                E.RULES["netHeight"] = float(nh)
            except (TypeError, ValueError):
                pass
        me = player_state_from_obs(obs["batsmen"][team], team)
        opp = player_state_from_obs(obs["batsmen"][1 - team], 1 - team)
        phase = obs.get("phase")
        if phase == "serve":
            if obs.get("server") == team:
                return self._defend(obs, me, opp, team)
            return self._receive_serve(obs, me, opp, team)
        if phase == "rally":
            ball = obs.get("shuttle")
            if not ball or not ball.get("alive"):
                return neutral_window()
            # A swing planned in the previous window may continue into this
            # one.  The observation is taken before the hit, so planning from
            # the incoming ball here would freeze us on the spot right after
            # our own contact (seen when a serve return left the player at the
            # net for ~9 frames).  Replay the plan's tail, then recover.
            tail_win = self._plan_tail_window(obs, me, opp, team, ball)
            if tail_win is not None:
                return tail_win
            if ball.get("lastTeam") == team:
                return self._defend(obs, me, opp, team)
            return self._rally_plan(obs, me, opp, team)
        self.plan_tail = []
        return neutral_window()

    def _observe(self, obs, team):
        """Track the serve release frame and the opponent's serve-return hits."""
        try:
            frame = obs.get("frame")
            if frame is None:
                return
            if obs.get("phase") == "serve" and obs.get("server") == team:
                rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
                self.serve_release = frame + rel
                self.serve_hit_pending = True
            for e in obs.get("events") or []:
                eid = e.get("id")
                if eid is None or eid <= self.seen_event:
                    continue
                self.seen_event = eid
                if (e.get("type") == "hit" and e.get("team") == 1 - team
                        and getattr(self, "serve_hit_pending", False)
                        and self.serve_release is not None and e.get("frame") is not None):
                    off = e["frame"] - self.serve_release
                    cx, cy = e.get("x"), e.get("y")
                    self.serve_hit_pending = False
                    if 0 < off < 40 and cx is not None and cy is not None:
                        self.return_contacts.append((cx, cy, off))
                        self.return_contacts = self.return_contacts[-6:]
                        kind = e.get("kind")
                        if kind in ("smash", "clear", "drop"):
                            self.last_return_swtype = 1
                        elif kind == "lift":
                            self.last_return_swtype = -1
                        if e.get("speed") is not None:
                            self.last_return_speed = e.get("speed")
        except Exception:
            pass

    def _learned_contact(self):
        """A stable opponent serve-return contact, if the last two agree."""
        rc = self.return_contacts
        if len(rc) < 2:
            return None
        x1, y1, o1 = rc[-2]
        x2, y2, o2 = rc[-1]
        if abs(x1 - x2) > 0.35 or abs(y1 - y2) > 0.35 or abs(o1 - o2) > 3:
            return None
        return (x2, y2, o2)

    # ------------------------------------------------------------------
    # Candidate enumeration
    # ------------------------------------------------------------------
    def _candidates(self, ball_pred, me, team, horizon):
        facing = me["facing"]
        reach = reach_of(me["stamina"])
        cands = []
        midswing = me["swing"] > 0
        # A jump raises the feet to 0.51 at best, which is what turns a
        # mid-height contact into a real down-press: the engine's smash speed
        # depends on the *ball* height (>=2.35 for a full smash), and standing
        # the overhead racket only reaches ~2.29 in the active window.
        jump_ok = (me.get("onGround", True) and not midswing
                   and me["stamina"] > JUMP_MIN_STAMINA)
        for t in range(1, min(horizon, len(ball_pred) - 1) + 1):
            samples = [s for s in ball_pred[t] if s[2]]
            if not samples:
                break
            if midswing:
                e = me["swingElapsed"] + t
                if e < R["swingWindup"] or e >= R["swingWindup"] + R["swingActive"]:
                    continue
                types = (me["swingType"],)
                elist = (e,)
            else:
                types = (1, -1)
                elist = [x for x in range(R["swingWindup"], R["swingWindup"] + R["swingActive"])
                         if t - x >= 1]
            py = me["y"]
            for swtype in types:
                for e in elist:
                    up, fwd = racket_offsets(e, swtype)
                    best = None
                    bestj = None
                    for j, (bx, by, alive) in enumerate(samples):
                        if team == 0 and bx > R["netX"] + 0.3:
                            continue
                        if team == 1 and bx < R["netX"] - 0.3:
                            continue
                        dy = by - (py + up)
                        if abs(dy) <= reach:
                            half = math.sqrt(max(0.0, reach * reach - dy * dy))
                            if best is None or half > best[2]:
                                best = (bx - facing * fwd, half, half, bx, by, j)
                        # Jump contacts: solve the jump frame that puts the
                        # feet where the ball is, and keep the best one.  The
                        # gate is loose; the residual check below enforces the
                        # racket reach, so a ball up to ~0.9 above the standing
                        # racket can still be met at the apex.
                        if jump_ok and swtype > 0 and by >= 2.28:
                            py_req = by - up - py
                            if -0.05 <= py_req <= 0.92:
                                got = jump_frame_for(py_req, t, tol=reach)
                                if got is not None:
                                    jf, _res = got
                                    n = t - jf
                                    if 1 <= n <= len(JUMP_Y):
                                        dyj = py_req - JUMP_Y[n - 1]
                                        if abs(dyj) <= reach:
                                            half = math.sqrt(max(0.0, reach * reach - dyj * dyj))
                                            if bestj is None or half > bestj[2]:
                                                bestj = (bx - facing * fwd, half, half,
                                                         bx, by, j, jf)
                    lo = 0.35 if team == 0 else R["netX"] + 0.35
                    hi = R["netX"] - 0.35 if team == 0 else R["courtLength"] - 0.35
                    if best is not None:
                        cands.append({"t": t, "e": e, "swtype": swtype,
                                      "px": clamp(best[0], lo, hi),
                                      "margin": best[1], "bx": best[3], "by": best[4],
                                      "j": best[5]})
                    if bestj is not None:
                        # The jump itself may fall beyond this window (the
                        # brain re-plans every 0.5 s); what matters now is that
                        # the servo targets the jump's take-off position.
                        cands.append({"t": t, "e": e, "swtype": swtype,
                                      "px": clamp(bestj[0], lo, hi),
                                      "margin": bestj[1], "bx": bestj[3], "by": bestj[4],
                                      "j": bestj[5], "jump_at": bestj[6]})
        return cands

    def _reachable_range(self, me, t, allow_sprint=True, jump_at=None):
        fwd = servo_inputs(me, 100.0, t, allow_sprint=allow_sprint, jump_at=jump_at)
        back = servo_inputs(me, -100.0, t, allow_sprint=allow_sprint, jump_at=jump_at)
        xf = sim_player(me, fwd, t)[-1]["x"]
        xb = sim_player(me, back, t)[-1]["x"]
        return min(xb, xf), max(xb, xf)

    def _eval_contact(self, cand, me, opp, team, ball_pred):
        facing = me["facing"]
        t = cand["t"]
        ox = opp_x_at(opp, t)
        shot = shot_from_contact(cand["bx"], cand["by"], cand["swtype"], facing, ox)
        traj = simulate_shot(cand["bx"], cand["by"], shot, facing, nframes=60)
        kind = shot["kind"]
        score = KIND_BASE.get(kind, 20.0)
        if self.clear_lover:
            score += {"smash": -150.0, "drop": 0.0, "clear": 120.0, "lift": 110.0}.get(kind, 0.0)
        dist_net = abs(cand["bx"] - R["netX"])
        if kind == "smash":
            score += (cand["by"] - 2.0) * 25.0
            score += max(0.0, 3.2 - dist_net) * 4.0
        elif kind == "drop":
            score += max(0.0, 3.0 - dist_net) * 6.0
        can, f = opponent_can_reach(traj, ox, opp["stamina"], opp["team"])
        if not can:
            score += 130.0
        else:
            score -= 10.0
        # A shot that crosses the net at blockable height while the opponent is
        # camping near the net is likely to come straight back: penalise it.
        cross_h = None
        prev = (cand["bx"], cand["by"])
        for (f, x, y) in traj:
            if (prev[0] - R["netX"]) * (x - R["netX"]) <= 0 and abs(x - prev[0]) > 1e-9:
                fr = (R["netX"] - prev[0]) / (x - prev[0])
                cross_h = prev[1] + (y - prev[1]) * fr
                break
            prev = (x, y)
        if (not self.smash_lover) and cross_h is not None and abs(ox - R["netX"]) < 1.9 and cross_h < 2.25:
            score -= 85.0
        # Reject shots that hit the net / land on our own side / fly out: the
        # engine's chooseShot falls back to a fixed angle when no candidate
        # clears the net, which is a self-inflicted lost point.
        ok = False
        if traj:
            lx, ly = traj[-1][1], traj[-1][2]
            if facing > 0:
                ok = (lx > R["netX"] + 0.05) and (lx < R["courtLength"] + 0.15)
            else:
                ok = (lx < R["netX"] - 0.05) and (lx > -0.15)
        if not ok or not self._trace_ok(cand["bx"], cand["by"], shot, facing, self.net_margin):
            score -= 400.0
        score += min(cand["margin"], 0.38) * 30.0
        return score, shot, traj

    # ------------------------------------------------------------------
    # Verification: simulate our own inputs against the predicted ball
    # ------------------------------------------------------------------
    def _verify_hit(self, me, inputs, pred, team, nframes):
        """Return (frame, ball, held_move, swing_type, best_clearance).

        best_clearance is the largest (reach - distance) achieved anywhere in
        the swing's active window.  Plans whose best alignment is only just
        inside the reach radius are fragile: the reach scales with stamina
        (0.38 -> 0.311 at zero stamina), so a sub-1% numeric difference
        between the plan and the real engine can turn a "hit" into a whiff.
        Callers use it to prefer solid contacts.
        """
        traj = sim_player(me, inputs, nframes)
        first = None
        best_clear = -1.0
        for f in range(1, min(nframes, len(traj) - 1) + 1):
            p = traj[f]
            if not in_window(p):
                continue
            rx, ry = E.Match.racket_at(p, p["swingElapsed"], p["swingType"])
            reach = reach_of(p["stamina"])
            samples = pred[f] if f < len(pred) else []
            for (bx, by, alive) in samples:
                if not alive:
                    continue
                if team == 0 and bx > R["netX"] + 0.3:
                    continue
                if team == 1 and bx < R["netX"] - 0.3:
                    continue
                d = math.hypot(bx - rx, by - ry)
                if d <= reach:
                    if first is None:
                        mv = (float(inputs[f - 1].get("move", 0.0))
                              if f - 1 < len(inputs) else 0.0)
                        first = (f, (bx, by), mv, p["swingType"])
                    if reach - d > best_clear:
                        best_clear = reach - d
        if first is None:
            return None
        return first + (best_clear,)

    @staticmethod
    def _shot_is_safe(traj, facing):
        if not traj:
            return False
        lx = traj[-1][1]
        if facing > 0:
            return (lx > R["netX"] + 0.05) and (lx < R["courtLength"] + 0.15)
        return (lx < R["netX"] - 0.05) and (lx > -0.15)

    @staticmethod
    def _trace_ok(sx, sy, shot, facing, margin=0.08):
        """Engine-identical trace: reject fallback shots and marginal net clears.

        chooseShot() falls back to a fixed angle without any net check when no
        candidate clears; at high nets that fallback lands on our own side.
        A small clearance margin also protects against a predicted contact
        being a few centimetres off the real one.
        """
        tr = E.Match.shot_trace(sx, sy, shot["angle"], shot["speed"], facing,
                                R["netHeight"])
        if tr["netHit"]:
            return False
        ny = tr["netY"]
        if ny is not None and ny < R["netHeight"] + margin:
            return False
        lx = tr["landX"]
        if facing > 0:
            return (R["netX"] + 0.05) < lx < (R["courtLength"] + 0.15)
        return -0.15 < lx < (R["netX"] - 0.05)

    # ------------------------------------------------------------------
    # Window construction
    # ------------------------------------------------------------------
    def _build_inputs(self, me, cand, hold_until=0, hold_x=None, nudge=False,
                      allow_sprint=True):
        t = cand["t"]
        e = cand["e"]
        jump_at = cand.get("jump_at")
        horizon = max(10, t + 1)
        if hold_until > 0 and hold_x is not None and hold_until < t:
            seg1 = servo_inputs(me, hold_x, hold_until, nframes=hold_until, hold_after=False,
                                allow_sprint=allow_sprint, jump_at=jump_at)
            cur = sim_player(me, seg1, len(seg1))[-1]
            rem = t - hold_until
            seg2 = servo_inputs(cur, cand["px"], rem, nframes=max(1, rem), hold_after=False,
                                allow_sprint=allow_sprint,
                                jump_at=(jump_at - hold_until) if jump_at else None)
            inputs = seg1 + seg2
        else:
            inputs = plan_control(me, cand["px"], t, horizon, hold_after=False,
                                  allow_sprint=allow_sprint, jump_at=jump_at)
        if me["swing"] <= 0:
            idx = (t - e) - 1
            if 0 <= idx < len(inputs):
                inputs[idx]["swing"] = cand["swtype"]
                if nudge:
                    inputs[idx]["move"] = float(me["facing"])
                    inputs[idx]["sprint"] = False
        return inputs

    @staticmethod
    def _format(inputs):
        out = []
        for i in range(10):
            inp = inputs[i] if i < len(inputs) else E.neutral()
            out.append({"move": round(float(inp.get("move", 0.0)), 4),
                        "jump": bool(inp.get("jump", False)),
                        "swing": int(inp.get("swing", 0)),
                        "sprint": bool(inp.get("sprint", False)),
                        "charge": False})
        return out

    def _hold_window(self, me, team, target_x=None, allow_sprint=False):
        if target_x is None:
            return [{"move": 0.0, "jump": False, "swing": 0, "charge": False,
                     "sprint": False} for _ in range(10)]
        inputs = plan_control(me, target_x, 10, 10, hold_after=False,
                              allow_sprint=allow_sprint)
        return self._format(inputs)

    def _plan_tail_window(self, obs, me, opp, team, ball):
        """Replay the part of the previous plan that falls in this window.

        A swing scheduled late in a window contacts the ball in the next one.
        This observation predates that contact, so planning from the incoming
        ball would ignore our own hit and stand still.  Use the stored tail
        of the plan, then spend any remaining frames recovering towards the
        defensive middle (the next window re-plans with fresh information).
        """
        if not self.plan_tail:
            return None
        # Only while the planned swing is actually in flight: outside that
        # window a stored plan is stale (the ball may have been struck
        # elsewhere) and replaying it would fight the fresh planning.
        if me.get("swing", 0) <= 0:
            self.plan_tail = []
            return None
        if ball is not None and ball.get("lastTeam") == team:
            # Our contact already happened: recovery is handled by _defend.
            self.plan_tail = []
            return None
        frame = obs.get("frame", 0)
        idx = (frame + 1) - self.plan_tail_frame0
        if idx < 0:
            return None
        if idx >= len(self.plan_tail):
            self.plan_tail = []
            return None
        pat = [dict(x) for x in self.plan_tail[idx:idx + 10]]
        if len(pat) < 10:
            cur = sim_player(me, pat, len(pat))[-1] if pat else me
            rem = 10 - len(pat)
            seg = servo_inputs(cur, self._mid_point(team), rem, nframes=rem,
                               hold_after=True)
            pat.extend(seg[:rem])
        self.plan_tail = []
        return self._format(pat)

    # ------------------------------------------------------------------
    # Serve receiving: attack the serve
    # ------------------------------------------------------------------
    def _receive_serve(self, obs, me, opp, team):
        ball = obs["shuttle"]
        rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
        server_facing = 1 if obs.get("server") == 0 else -1
        pred = predict_serve(ball, rel, server_facing, 46)
        got = self._intercept(obs, me, opp, team, pred, budget=18, early_bias=0.4)
        if got is not None:
            return got
        return self._hold_window(me, team)

    # ------------------------------------------------------------------
    # Defence: force the short smash at the tie point, then chase it
    # ------------------------------------------------------------------
    def _mid_point(self, team):
        return 4.0 if team == 0 else R["courtLength"] - 4.0

    def _tie_point(self, team):
        return 2.95 if team == 0 else 10.45

    def _camp_point(self, team):
        return 6.35 if team == 0 else R["netX"] + 0.35

    def _tie_x(self, team):
        if self.def_mode == "camp":
            return self._camp_point(team)
        if self.def_mode == "mid":
            return self._mid_point(team)
        return self._tie_point(team)

    def _def_x(self, team, serve_return=False):
        """Stance to use while waiting for the opponent's return.

        Standing at the tie point (< 3.05 from our baseline) makes the
        opponent's smash target the slow near-net corner instead of the
        34 m/s deep corner, which is physically unreachable.  General rally
        defence keeps the configured mode.
        """
        if serve_return:
            return self._tie_point(team)
        return self._tie_x(team)

    def _hold_then_go(self, me, hold_x, hold_frames, then_x):
        """Window: stand at hold_x for hold_frames, then run to then_x."""
        hold_frames = int(clamp(hold_frames, 0, 10))
        if hold_frames > 0:
            seg1 = servo_inputs(me, hold_x, hold_frames, nframes=hold_frames,
                                hold_after=False)
            cur = sim_player(me, seg1, hold_frames)[-1]
        else:
            seg1 = []
            cur = me
        rem = 10 - hold_frames
        if rem > 0:
            seg2 = servo_inputs(cur, then_x, rem, nframes=rem, hold_after=True)
        else:
            seg2 = []
        return self._format(seg1 + seg2)

    # ------------------------------------------------------------------
    # Serve-return run-up
    #
    # The opponent's smash target is chosen from our x at the strike frame:
    # x < 3.05 (mirror > 10.35) forces the slow near-net corner (target 5.1,
    # ~0.35 s flight), anything else gets the 34 m/s deep corner which is
    # physically impossible to return.  Standing still on the tie point and
    # accelerating *after* the strike wastes the first 0.2 s; instead we wait
    # at a launch point and time a sprint so that we are at x ~ 2.6 already
    # moving at full speed when the opponent strikes, while still being below
    # the threshold at that exact frame.
    # ------------------------------------------------------------------
    def _launch_x(self, team):
        return 2.11 if team == 0 else R["courtLength"] - 2.11

    # ------------------------------------------------------------------
    # Serve-return defence ("deep-corner bait")
    #
    # The opponent's serve-return smash targets whichever corner is farther
    # from us: standing closer to the net than the bisector (3.65 from the
    # net) forces the DEEP corner (12.4 / 1.0).  The incoming trajectory is
    # therefore known once we know their contact point and timing, and we can
    # pre-schedule the counter swing several frames before the ball arrives.
    #
    # Three things make this reliable (see _deep_bait_window):
    #   * project the contact mid-frame (the engine hits between substeps);
    #   * invert the reported return speed to recover the striker's forward
    #     nudge, which controls the target to +-0.05 (0.4 grid of x error
    #     otherwise -- more than the 0.38 racket reach);
    #   * search a set of stances and swing timings, including a swing that
    #     starts in the previous window and sweeps into this one.
    # ------------------------------------------------------------------
    def _bait_x(self, team):
        mode = os.environ.get("BAD_BAIT_MODE", "search")
        if mode == "net":
            return R["netX"] - 0.35 if team == 0 else R["netX"] + 0.35
        if mode == "mid":
            return 2.0 if team == 0 else R["courtLength"] - 2.0
        if mode == "search":
            return self._bait_stances(team)[0]
        return 3.30 if team == 0 else R["courtLength"] - 3.30

    def _serve_contact(self, obs, me, opp, team, pred):
        """Predicted (t_contact, contact_x, contact_y) of the serve return."""
        frame = obs.get("frame", 0)
        learned = self._learned_contact() if self.learn else None
        if learned is not None and self.serve_release is not None:
            cx, cy, off = learned
            return float(self.serve_release + off - frame), cx, cy
        me_pred = dict(me)
        me_pred["x"] = self._bait_x(team)
        me_pred["vx"] = 0.0
        self.last_projection = None
        got = self._project_opponent(pred, me_pred, opp, team)
        if got is None or self.last_projection is None:
            return None, None, None
        c = self.last_projection["c"]
        return float(got[0]), c["bx"], c["by"]

    def _bait_stances(self, team):
        """Candidate stances on our side, as distances from the net.

        d < 3.65 keeps the opponent's serve-return target on the DEEP corner
        (12.4 / 1.0), so the incoming trajectory is the same for all of them;
        only our racket geometry differs.  The planner tests each.
        """
        env = os.environ.get("BAD_BAIT_D", "3.40,2.30,1.70,1.10,0.50")
        out = []
        for part in env.split(","):
            try:
                d = float(part)
            except ValueError:
                continue
            x = (R["netX"] - d) if team == 0 else (R["netX"] + d)
            lo = 0.35 if team == 0 else R["netX"] + 0.35
            hi = R["netX"] - 0.35 if team == 0 else R["courtLength"] - 0.35
            x = clamp(x, lo, hi)
            if all(abs(x - y) > 0.05 for y in out):
                out.append(x)
        return out or [(R["netX"] - 3.3) if team == 0 else (R["netX"] + 3.3)]

    def _deep_bait_window(self, obs, me, opp, team, ball, pred):
        stances = self._bait_stances(team)
        bait = stances[0]
        hold = plan_control(me, bait, 10, 10, hold_after=False, allow_sprint=False)
        t_c, cx, cy = self._serve_contact(obs, me, opp, team, pred)
        if t_c is None or cx is None:
            return self._format(hold)
        if t_c < 1.0:
            # The predicted contact already happened: the observed trajectory
            # is the real return, so chase it directly instead of re-creating it.
            got = self._intercept(obs, me, opp, team, pred, budget=18,
                                  allow_sprint=False)
            if got is not None:
                return got
            return self._format(hold)
        if t_c > 13.5:
            return self._format(hold)
        swtype = getattr(self, "last_return_swtype", None) or (1 if cy > 1.2 else -1)
        kind, _target = E.Match.shot_kind_and_target(cx, cy, swtype, opp["facing"], bait)
        if kind != "smash":
            log("serve return predicted %s (no bait swing) t=%.1f c=(%.2f,%.2f)" % (
                kind, t_c, cx, cy))
            return self._format(hold)
        if self.serve_release is None:
            return self._format(hold)
        proj = self._project_from_contact(pred, cx, cy, max(1, int(round(t_c))),
                                          {"x": bait}, opp, team)
        if proj is None:
            return self._format(hold)
        variants = proj[1]
        tc = int(round(t_c))
        lo = max(0, tc - 6)
        hi = min(9, tc + 4)
        # The counter contact is 3-7 frames after the opponent's contact, which
        # may fall in the next window.  A swing scheduled at the end of this
        # window keeps sweeping into the next one, and the early hold check in
        # _defend() freezes the stance while it is in flight.  Extend the
        # simulation accordingly (neutral frames = standing still).
        nv = max(14, tc + 9)
        best = None
        for stance in stances:
            if stance != bait:
                hold_s = plan_control(me, stance, 10, 10, hold_after=False,
                                      allow_sprint=False)
            else:
                hold_s = hold
            for swtype in (1, -1):
                for idx in range(lo, hi + 1):
                    trial = [dict(x) for x in hold_s]
                    trial[idx]["swing"] = swtype
                    cover = 0
                    hit0 = None
                    for vi, pv in enumerate(variants[:3]):
                        h = self._verify_hit(me, trial, pv, team, nv)
                        if h is not None and h[0] <= nv:
                            cover += 1
                            if vi == 0:
                                hit0 = h
                    if cover == 0:
                        continue
                    score = 0.0
                    clr = hit0[4] if hit0 is not None else -1.0
                    if hit0 is not None:
                        f, (bx, by), mv, st = hit0[:4]
                        cand = {"t": f, "e": 0, "swtype": st, "px": me["x"],
                                "margin": 0.2, "bx": bx, "by": by}
                        score, _shot, _traj = self._eval_contact(cand, me, opp, team,
                                                                 variants[0])
                        if score < 0.0:
                            continue
                    # Prefer a plan that reliably meets the best-estimate
                    # trajectory (hit0), then coverage, then shot quality; among
                    # equal plans keep the one nearest to the anchor stance.
                    key = (hit0 is not None, cover, min(clr, 0.20), score,
                           -abs(stance - bait), -abs(idx - (tc - 2)))
                    if best is None or key > best[0]:
                        best = (key, trial, swtype, idx, hit0, stance)
        if best is None:
            log("deep bait: no swing verified t=%d c=(%.2f,%.2f)" % (tc, cx, cy))
            return self._format(hold)
        if best[4] is not None:
            self.bait_hold_until = obs.get("frame", 0) + best[4][0] + 2
        else:
            self.bait_hold_until = obs.get("frame", 0) + nv
        log("deep bait swing cover=%d/%d t=%d c=(%.2f,%.2f) type=%d idx=%d stance=%.2f hit=%s" % (
            best[0][1], len(variants), tc, cx, cy, best[2], best[3], best[5], best[4]))
        return self._format(best[1])

    def _serve_return_defense(self, obs, me, opp, team, ball, pred):
        if self.deadbait:
            return self._deep_bait_window(obs, me, opp, team, ball, pred)
        frame = obs.get("frame", 0)
        learned = self._learned_contact() if self.learn else None
        t_contact = None
        if self.serve_release is not None:
            # Bias the predicted contact late: being early only costs speed,
            # being late pushes us past the 3.05 threshold and flips the
            # opponent's target to the unreachable deep corner.
            off = float(learned[2]) if learned is not None else 14.0
            t_contact = self.serve_release + off - frame
        me_pred = dict(me)
        me_pred["x"] = self._launch_x(team)
        me_pred["vx"] = 0.0
        projected = None
        if learned is not None and t_contact is not None and 1.0 <= t_contact <= 40.0:
            cx, cy, off = learned
            projected = self._project_from_contact(pred, cx, cy,
                                                   int(round(t_contact)),
                                                   me_pred, opp, team)
            if projected is not None:
                log("learned serve return (%.2f,%.2f) off=%d t=%.1f" % (cx, cy, off, t_contact))
        if projected is None:
            projected = self._project_opponent(pred, me_pred, opp, team)
        variants = None
        if projected is not None:
            t_proj, variants = projected
            if t_contact is None:
                t_contact = float(t_proj)
        if t_contact is None:
            t_contact = 8.0
        inputs, _swung = self._runup_inputs(me, team, t_contact, variants, opp)
        return self._format(inputs)

    def _runup_inputs(self, me, team, t_contact, variants, opp):
        facing = me["facing"]
        launch = self._launch_x(team)
        n = 10
        tpre = max(0.0, float(t_contact) - 4.0)
        npre = max(0, min(n, int(math.floor(tpre + 1e-6))))
        inputs = []
        cur = dict(me)
        if npre > 0:
            seg = servo_inputs(cur, launch, npre, nframes=npre, hold_after=False,
                               allow_sprint=False)
            inputs.extend(seg[:npre])
            cur = sim_player(cur, seg[:npre], npre)[-1]
        while len(inputs) < n:
            inp = {"move": float(facing),
                   "sprint": bool(cur["stamina"] > 8.0 and cur["onGround"])}
            inputs.append(inp)
            q = dict(cur)
            q["held"] = inp
            E.Match.update_player(DummyMatch(), q)
            cur = q
        if not variants:
            return inputs, False
        # Try to strike inside this very window: when the opponent contacts
        # early in the window the return lands before the next window can
        # react, so the swing has to be pre-scheduled from the prediction.
        best = None
        for swtype in (1, -1):
            for idx in range(n):
                trial = [dict(x) for x in inputs]
                trial[idx]["swing"] = swtype
                hits = 0
                hit0 = None
                for vi, pv in enumerate(variants[:3]):
                    h = self._verify_hit(me, trial, pv, team, n)
                    if h is not None and h[0] <= n:
                        hits += 1
                        if vi == 0:
                            hit0 = h
                if hit0 is None:
                    continue
                f, (bx, by), mv, st = hit0[:4]
                cand = {"t": f, "e": 0, "swtype": st, "px": me["x"],
                        "margin": 0.2, "bx": bx, "by": by}
                score, shot, traj = self._eval_contact(cand, me, opp, team, variants[0])
                score += 120.0 * min(hit0[4], 0.2)
                if score < -200.0:
                    continue
                key = (hits, score)
                if best is None or key > best[0]:
                    best = (key, trial)
        if best is not None:
            log("runup strike cover=%d/%d score=%.1f" % (best[0][0], min(3, len(variants)),
                                                         best[0][1]))
            return best[1], True
        return inputs, False

    def _defend(self, obs, me, opp, team):
        ball = obs["shuttle"]
        # A pre-scheduled counter swing (deep bait) must not be disturbed: its
        # racket/ball alignment assumes we stand still while it sweeps.
        if (me.get("swing", 0) > 0
                and obs.get("frame", 0) < getattr(self, "bait_hold_until", -1)):
            return self._hold_window(me, team, me["x"])
        if obs.get("phase") == "serve":
            rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
            server_facing = 1 if obs.get("server") == 0 else -1
            pred = predict_serve(ball, rel, server_facing, 52)
        else:
            pred = predict_shuttle(ball, 52)
        # While our own serve is still frozen we keep the usual stance: moving
        # before release would shift the serve origin.  Once the serve is in
        # the air (rally == 0, lastTeam == us) we defend the return from the
        # tie point and do not leave it until the opponent actually strikes.
        serve_return = (obs.get("phase") == "rally" and obs.get("rally", 0) == 0
                        and ball.get("lastTeam") == team)
        if obs.get("phase") == "serve" and obs.get("server") == team:
            # beginServe() builds the shuttle at the server's home position and
            # never moves it again during the freeze, so walking around before
            # release does NOT change the serve.  Use the 0.8 s freeze to walk
            # to the run-up launch point instead of hugging the baseline.
            if self.deadbait:
                return self._hold_window(me, team, self._bait_x(team))
            if self.runup:
                return self._hold_window(me, team, self._launch_x(team))
            rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
            if rel > 0:
                return self._hold_then_go(me, me["x"], rel, self._tie_point(team))
        if serve_return and (self.deadbait or self.runup):
            got = self._serve_return_defense(obs, me, opp, team, ball, pred)
            if got is not None:
                return got
        tie = self._def_x(team, serve_return=serve_return)
        opp_team = 1 - team
        if (ball.get("lastTeam") == opp_team and obs.get("phase") != "serve"
                and me.get("swing", 0) > 0
                and obs.get("frame", 0) < self.bait_hold_until):
            # A deep-bait counter swing is already in flight: keep the stance
            # so the pre-computed racket/ball alignment is preserved.
            return self._hold_window(me, team, me["x"])
        if ball.get("lastTeam") == opp_team and obs.get("phase") != "serve":
            got = self._intercept(obs, me, opp, team, pred, budget=18)
            if got is not None:
                return got
            # No verified interception: at least run at the predicted landing
            # if it is on our side; otherwise keep the defensive stance.
            land = self._predicted_landing(pred)
            if land is not None:
                lo = 0.35 if team == 0 else R["netX"] + 0.35
                hi = R["netX"] - 0.35 if team == 0 else R["courtLength"] - 0.35
                if lo <= land <= hi:
                    return self._hold_window(me, team, clamp(land, lo, hi))
            return self._hold_window(me, team, tie)
        # project the opponent's attack
        me_pred = dict(me)
        me_pred["x"] = tie
        me_pred["vx"] = 0.0
        projected = None
        if self.learn and obs.get("phase") == "serve" and obs.get("server") == team:
            learned = self._learned_contact()
            if learned is not None:
                cx, cy, off = learned
                rel = int(round(float(obs.get("serveLeft", 0)) * R["hz"]))
                t_learn = rel + off
                if 1 <= t_learn <= 40:
                    projected = self._project_from_contact(pred, cx, cy, t_learn, me_pred, opp, team)
                    if projected is not None:
                        log("learned opp contact (%.2f,%.2f) t=%d" % (cx, cy, t_learn))
        if projected is None:
            projected = self._project_opponent(pred, me_pred, opp, team)
        if projected is not None:
            t_contact, variants = projected
            if serve_return and t_contact >= 4:
                # The opponent will strike later in this window.  Stay on the
                # tie point for the whole window: any forward move now would
                # push our x past the 3.05 threshold and turn the return back
                # into the 34 m/s deep-corner smash.  The next window starts
                # after the strike and can chase the actual (slow) ball.
                return self._hold_window(me, team, tie)
            if 1 <= t_contact <= 40:
                got = self._intercept(obs, me, opp, team, variants[0], budget=18,
                                      only_after=max(1, t_contact),
                                      hold_until=t_contact, hold_x=tie,
                                      variants=variants)
                if got is not None:
                    return got
                land = self._predicted_landing(variants[0])
                if land is not None:
                    lo = 0.35 if team == 0 else R["netX"] + 0.35
                    hi = R["netX"] - 0.35 if team == 0 else R["courtLength"] - 0.35
                    # Do not chase the projected landing before the opponent
                    # has hit: that moves us off the tie point and flips the
                    # opponent's target back to the unreachable deep corner.
                    if serve_return or t_contact >= 2:
                        return self._hold_then_go(me, tie, t_contact,
                                                  clamp(land, lo, hi))
                    return self._hold_window(me, team, clamp(land, lo, hi))
        return self._hold_window(me, team, tie)

    @staticmethod
    def _predicted_landing(pred):
        for f in range(len(pred) - 1, 0, -1):
            for (bx, by, alive) in pred[f]:
                if not alive:
                    return bx
        return None

    def _project_from_contact(self, pred, cx, cy, t, me, opp, team, swtype=None):
        opp_team = 1 - team
        if swtype is None:
            swtype = getattr(self, "last_return_swtype", None)
        if swtype is None:
            swtype = 1 if cy > 1.2 else -1
        ms = max_speed_of(opp["stamina"])
        est_fwd = clamp((opp["vx"] / ms) * opp["facing"], 0.0, 1.0) if ms > 1e-6 else 0.0
        # The opponent's smash target is deepX + 0.6*forward, and forward is the
        # only unknown left.  The hit event reports the shot speed, which is
        # strictly increasing in forward, so invert it: this pins the target to
        # ~0.05 grid instead of guessing 0/0.5/1.0 (a 0.4 grid of x error at the
        # interception point is more than the racket reach).
        fwd_best = est_fwd
        sp = getattr(self, "last_return_speed", None)
        if sp is not None:
            try:
                sp = float(sp)
            except (TypeError, ValueError):
                sp = None
        if sp is not None:
            best = None
            for i in range(0, 9):
                f = i / 8.0
                sh = shot_from_contact(cx, cy, swtype, opp["facing"], me["x"], forward=f)
                d = abs(sh["speed"] - sp)
                if best is None or d < best[0]:
                    best = (d, f)
            if best is not None and best[0] < 2.0:
                for i in range(-2, 3):
                    f = clamp(best[1] + i * 0.06, 0.0, 1.0)
                    sh = shot_from_contact(cx, cy, swtype, opp["facing"], me["x"],
                                           forward=f)
                    d = abs(sh["speed"] - sp)
                    if d < best[0]:
                        best = (d, f)
                fwd_best = best[1]
        forwards = []
        for f in (fwd_best, est_fwd, 0.0, 1.0):
            if all(abs(f - g) > 0.2 for g in forwards):
                forwards.append(f)
        rem = 1
        if 0 <= t < len(pred):
            j = contact_substep(pred[t], cx, cy)
            if j is not None:
                rem = R["substeps"] - 1 - j
        variants = []
        for fwd in forwards:
            sh = shot_from_contact(cx, cy, swtype, opp["facing"], me["x"], forward=fwd)
            sf = shot_frames_partial(cx, cy, sh, opp["facing"], rem, 55)
            combined = []
            for f in range(t + 56):
                if f < t:
                    combined.append(pred[f] if f < len(pred) else [(cx, cy, False)])
                elif f == t:
                    combined.append(sf[0])
                else:
                    k = f - t
                    combined.append(sf[k] if k < len(sf) else [(cx, cy, False)])
            variants.append(combined)
        return t, variants

    def _project_opponent(self, pred, me, opp, team):
        opp_team = 1 - team
        cands = self._candidates(pred, opp, opp_team, 40)
        if not cands:
            return None
        best = None
        for c in cands:
            lo, hi = self._reachable_range(opp, c["t"])
            if c["px"] < lo - 0.08 or c["px"] > hi + 0.08:
                continue
            score, shot, traj = self._eval_contact(c, opp, me, opp_team, pred)
            score -= c["t"] * 0.4
            if best is None or score > best[0]:
                best = (score, c, shot)
        if best is None:
            return None
        _, c, shot = best
        t = c["t"]
        # The struck shuttle also gets a forward nudge from the striker's held
        # move; model a few possibilities so the plan is robust.
        ms = max_speed_of(opp["stamina"])
        est_fwd = clamp((opp["vx"] / ms) * opp["facing"], 0.0, 1.0) if ms > 1e-6 else 0.0
        forwards = []
        for f in (0.0, est_fwd, 1.0):
            if all(abs(f - g) > 0.2 for g in forwards):
                forwards.append(f)
        variants = []
        j = c.get("j")
        rem = R["substeps"] - 1 - j if j is not None else 1
        for fwd in forwards:
            sh = shot_from_contact(c["bx"], c["by"], c["swtype"], opp["facing"],
                                   me["x"], forward=fwd)
            sf = shot_frames_partial(c["bx"], c["by"], sh, opp["facing"], rem, 55)
            combined = []
            for f in range(t + 56):
                if f < t:
                    combined.append(pred[f] if f < len(pred) else [(c["bx"], c["by"], False)])
                elif f == t:
                    combined.append(sf[0])
                else:
                    k = f - t
                    combined.append(sf[k] if k < len(sf) else [(c["bx"], c["by"], False)])
            variants.append(combined)
        log("project opp: t=%d e=%d type=%d at (%.2f,%.2f) -> %s fwd=%s" % (
            t, c["e"], c["swtype"], c["bx"], c["by"], shot["kind"],
            [round(x, 2) for x in forwards]))
        self.last_projection = {"t": t, "c": c, "shot": shot,
                                "forwards": forwards}
        return t, variants

    # ------------------------------------------------------------------
    # Generic interception
    # ------------------------------------------------------------------
    def _intercept(self, obs, me, opp, team, pred, budget=18, only_after=0,
                   hold_until=0, hold_x=None, early_bias=0.3, variants=None,
                   allow_sprint=True):
        preds = [pred] if not variants else variants
        cands = self._candidates(pred, me, team, min(42, len(pred) - 1))
        scored = []
        for c in cands:
            if c["t"] < only_after:
                continue
            lo, hi = self._reachable_range(me, c["t"], allow_sprint=allow_sprint,
                                           jump_at=c.get("jump_at"))
            if c["px"] < lo - 0.06 or c["px"] > hi + 0.06:
                continue
            score, shot, traj = self._eval_contact(c, me, opp, team, pred)
            score -= c["t"] * early_bias
            # Chasing a "better" contact far from where we stand costs legs.
            # In flat-drive loops the early clear is only ~16 points better
            # than the nearby lift, while the extra run can decide a long
            # rally's stamina.  Configurable for offline comparison.
            score -= self.move_pen * abs(c["px"] - me["x"])
            # Jumping burns 10 stamina and 8 frames of air control: pay that
            # back only when the higher contact genuinely buys a better shot.
            if c.get("jump_at"):
                score -= self.jump_pen
            scored.append((score, c, shot))
        scored.sort(key=lambda x: -x[0])
        best = None
        best_marginal = None
        for score, c, shot in scored[:budget]:
            inputs = self._build_inputs(me, c, hold_until, hold_x,
                                        nudge=(self.nudge and only_after == 0 and hold_until == 0),
                                        allow_sprint=allow_sprint)
            hits = []
            for pv in preds:
                hits.append(self._verify_hit(me, inputs, pv, team, max(12, c["t"] + 2)))
            good = sum(1 for h in hits if h is not None)
            if good == 0:
                continue
            h0 = next(h for h in hits if h is not None)
            fwd = clamp(h0[2] * me["facing"], 0.0, 1.0)
            real = shot_from_contact(h0[1][0], h0[1][1], h0[3], me["facing"],
                                     opp_x_at(opp, h0[0]), forward=fwd)
            real_traj = simulate_shot(h0[1][0], h0[1][1], real, me["facing"], nframes=60)
            if (not self._shot_is_safe(real_traj, me["facing"])
                    or not self._trace_ok(h0[1][0], h0[1][1], real, me["facing"], self.net_margin)):
                score -= 400.0
                if score < 0:
                    continue
            clearance = h0[4] if len(h0) > 4 else 0.0
            # A contact that only just fits inside the reach radius can miss in
            # the real engine (the reach shrinks with stamina).  Prefer plans
            # with >=0.05 grid of margin; fall back to marginal ones only if
            # nothing solid exists.
            if clearance >= 0.05:
                score += 60.0 * min(clearance, 0.20)
                rank = (good, 1, score)
                if best is None or rank > best[0]:
                    best = (rank, inputs, c, shot, hits, score)
                if good == len(preds):
                    break
            else:
                rank = (good, 0, score)
                if best_marginal is None or rank > best_marginal[0]:
                    best_marginal = (rank, inputs, c, shot, hits, score)
        if best is None:
            best = best_marginal
        if best is None:
            return None
        rank, inputs, c, shot, hits, score = best
        if c.get("jump_at"):
            log("jump contact t=%d e=%d y=%.2f jf=%d score=%.1f" % (
                c["t"], c["e"], c["by"], c["jump_at"], score))
        self.plan_tail = [dict(x) for x in inputs[10:]]
        self.plan_tail_frame0 = obs.get("frame", 0) + 11
        log("intercept: t=%d e=%d type=%d px=%.2f score=%.1f %s cover=%d/%d hit@%s" % (
            c["t"], c["e"], c["swtype"], c["px"], score, shot["kind"],
            rank[0], len(preds), [h[0] if h else None for h in hits]))
        return self._format(inputs)

    # ------------------------------------------------------------------
    # Rally
    # ------------------------------------------------------------------
    def _rally_plan(self, obs, me, opp, team):
        ball = obs["shuttle"]
        pred = predict_shuttle(ball, 46)
        land = None
        for f in range(len(pred) - 1, 0, -1):
            for (bx, by, alive) in pred[f]:
                if not alive:
                    land = (bx, by)
                    break
            if land:
                break
        if land is not None:
            if team == 0 and land[0] < -0.1:
                return self._hold_window(me, team, 4.0)
            if team == 1 and land[0] > R["courtLength"] + 0.1:
                return self._hold_window(me, team, R["courtLength"] - 4.0)
        got = self._intercept(obs, me, opp, team, pred,
                              allow_sprint=self.rally_sprint)
        if got is not None:
            return got
        tx = None
        for f in range(1, len(pred) - 1):
            for (bx, by, alive) in pred[f]:
                if not alive:
                    tx = bx
                    break
            if tx is not None:
                break
        if tx is not None:
            return self._hold_window(me, team, clamp(tx, 0.35 if team == 0 else 7.05,
                                                    6.35 if team == 0 else 13.05))
        return self._hold_window(me, team)

# ===================== main loop =====================





def _neutral():
    return {"move": 0.0, "jump": False, "swing": 0, "charge": False, "sprint": False}


def main():
    try:
        sys.stdin.reconfigure(encoding="utf-8", errors="replace")
    except Exception:
        pass
    try:
        sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    except Exception:
        pass
    brain = Brain()
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            obs = json.loads(line)
        except Exception:
            obs = {}
        try:
            frames = brain.act(obs)
            if not isinstance(frames, list) or len(frames) != 10:
                raise ValueError("bad window")
            payload = []
            for f in frames:
                if not isinstance(f, dict):
                    raise ValueError("bad frame")
                payload.append([{
                    "move": float(f.get("move", 0.0)),
                    "jump": bool(f.get("jump", False)),
                    "swing": int(f.get("swing", 0)),
                    "charge": bool(f.get("charge", False)),
                    "sprint": bool(f.get("sprint", False)),
                }])
        except Exception:
            payload = [[_neutral()] for _ in range(10)]
        out.write(json.dumps({"inputs": payload}, separators=(",", ":")) + "\n")
        out.flush()


if __name__ == "__main__":
    main()